<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, ref, shallowRef } from 'vue'
import { useRouter } from 'vue-router'
import { ArrowLeft, Play, Pause, RotateCcw, Route, FileDown, ScanEye, Navigation, Battery, Mountain, Gauge, Camera, Send, Box, X, Clock, MoveUpRight, Maximize2, Settings2, Leaf, Activity, ChevronRight, Check, Layers } from 'lucide-vue-next'
import InspectionHeader from '../components/common/InspectionHeader.vue'
import PestSimulationScene from '../components/pest/PestSimulationScene.vue'
import { observationTargets, adaptivePlan, routeObservations, observationCoverage, viewSector, simulationRoutes, routeLength, sampleRoute, returnRoute, simulationBattery, simulationCommand, readReports, simulationReportHtml, type ViewStrategy, type PlantObservation, type Position3, type MissionStage, type SimulationSample, type SimulationReport, type ViewpointResult } from '../utils/pestSimulation'

const router = useRouter()
const sceneRef = ref<InstanceType<typeof PestSimulationScene> | null>(null)
const viewport = ref<HTMLElement | null>(null)
const ready = ref(false), sceneError = ref(''), optimizing = ref(false)
const routeId = ref(simulationRoutes[0]!.id), stage = ref<MissionStage>('idle'), resumeStage = ref<'running' | 'returning'>('running')
const route = computed(() => simulationRoutes.find(item => item.id === routeId.value) || simulationRoutes[0]!)
const points = shallowRef<Position3[]>(route.value.points)
const segmentDistance = ref(0), totalDistance = ref(0), elapsed = ref(0), speed = ref(4), timeScale = ref(1)
const cameraMode = ref('overview'), targetIndex = ref(0), missionId = ref(`SIM-${Date.now()}`)
const samples = ref<SimulationSample[]>([]), viewpoints = ref<ViewpointResult[]>([])
const running = computed(() => stage.value === 'running' || stage.value === 'returning')
const length = computed(() => routeLength(points.value))
const progress = computed(() => Math.min(100, length.value ? segmentDistance.value / length.value * 100 : 0))
const pose = computed(() => sampleRoute(points.value, segmentDistance.value))
const battery = computed(() => simulationBattery(elapsed.value))
const statusLabels: Record<MissionStage, string> = { idle: '待命', running: '巡航中', paused: '已暂停', returning: '返航中', completed: '已完成' }
const status = computed(() => statusLabels[stage.value])
const notice = ref('一号试验田已就绪，选择巡检方案后即可开始任务。')
const modal = ref<'' | 'routes' | 'models' | 'reports' | 'reset' | 'viewpoints'>('')
const draftRoute = ref(routeId.value)
const logs = ref<{ time: string; message: string }[]>([])
const command = ref('')
const messages = ref<{ role: 'user' | 'assistant'; text: string }[]>([{ role: 'assistant', text: '一号试验田已准备就绪。建议先完成全域巡查，再对重点样株进行多角度观察。您可以直接发送“开始巡检”“暂停”“返航”或“优化视点”。' }])
const observations = ref<PlantObservation[]>([]), strategy = ref<ViewStrategy>('semantic')
const visitedSectors = computed(() => observations.value.filter(item => item.target === targetIndex.value && item.visible >= .5).map(item => item.sector))
const coarseDone = computed(() => routeId.value !== 'maize-orbit' && (stage.value === 'returning' || resumeStage.value === 'returning' ? totalDistance.value : segmentDistance.value) >= adaptivePlan.coarseEnd)
const phaseIndex = computed(() => stage.value === 'returning' || resumeStage.value === 'returning' || stage.value === 'completed' ? 2 : routeId.value === 'maize-adaptive' && segmentDistance.value >= adaptivePlan.coarseEnd ? 1 : 0)
const observedPlants = computed(() => observationTargets.filter((_, index) => observationCoverage(observations.value, index) > 0).length)
const remaining = computed(() => Math.max(0, (length.value - segmentDistance.value) / speed.value))
const strategyName = computed(() => ({ fixed: '标准观察', coverage: '覆盖优先', semantic: '重点区域优先' })[strategy.value])
const lastView = computed(() => viewpoints.value.at(-1))
function plantState(index: number) { return observationCoverage(observations.value, index) ? '已观测' : !coarseDone.value ? '待巡查' : observationTargets[index]!.cue > .8 ? '重点观察' : observationTargets[index]!.cue < .2 ? '常规巡查' : '待复核' }
function openRoutes() { draftRoute.value = routeId.value; modal.value = 'routes' }
const reports = ref<SimulationReport[]>([])
const isFullscreen = ref(false)
function fullscreenChanged() { isFullscreen.value = document.fullscreenElement === viewport.value }
document.addEventListener('fullscreenchange', fullscreenChanged)
const REPORT_KEY = 'uav:pest-simulation:reports:maize:v2', MISSION_KEY = 'uav:pest-simulation:mission:maize:v2'
let lastSample = -1, unmounted = false

function log(message: string) { logs.value.unshift({ time: new Date().toLocaleTimeString('zh-CN', { hour12: false }), message }); logs.value = logs.value.slice(0, 50) }
function notify(message: string) { notice.value = message; log(message); checkpoint() }
function checkpoint() {
  try { localStorage.setItem(MISSION_KEY, JSON.stringify({ routeId: routeId.value, points: points.value, stage: stage.value, resumeStage: resumeStage.value, segmentDistance: segmentDistance.value, totalDistance: totalDistance.value, elapsed: elapsed.value, speed: speed.value, timeScale: timeScale.value, missionId: missionId.value, samples: samples.value, viewpoints: viewpoints.value, observations: observations.value, strategy: strategy.value, logs: logs.value })) }
  catch { notice.value = '浏览器存储不可用；当前仍可巡航和下载报告，但刷新后不能恢复任务。' }
}
try {
  reports.value = readReports(localStorage.getItem(REPORT_KEY))
  const saved = JSON.parse(localStorage.getItem(MISSION_KEY) || 'null')
  if (saved && simulationRoutes.some(item => item.id === saved.routeId) && ['idle', 'running', 'paused', 'returning', 'completed'].includes(saved.stage) && Array.isArray(saved.points) && saved.points.length >= 2 && saved.points.length <= 30 && saved.points.every((point: unknown) => Array.isArray(point) && point.length === 3 && point.every(Number.isFinite)) && [saved.segmentDistance, saved.totalDistance, saved.elapsed].every((value: unknown) => typeof value === 'number' && Number.isFinite(value) && value >= 0)) {
    routeId.value = saved.routeId; points.value = saved.points
    segmentDistance.value = Math.min(saved.segmentDistance, routeLength(saved.points)); totalDistance.value = saved.totalDistance; elapsed.value = saved.elapsed
    resumeStage.value = saved.stage === 'returning' || saved.resumeStage === 'returning' ? 'returning' : 'running'
    stage.value = saved.stage === 'running' || saved.stage === 'returning' ? 'paused' : saved.stage
    speed.value = [2, 4, 8].includes(saved.speed) ? saved.speed : 4; timeScale.value = [1, 2, 4].includes(saved.timeScale) ? saved.timeScale : 1
    if (typeof saved.missionId === 'string') missionId.value = saved.missionId
    if (Array.isArray(saved.logs)) logs.value = saved.logs.filter((row: { time: string; message: string }) => row && typeof row.time === 'string' && typeof row.message === 'string').slice(0, 50)
    if (Array.isArray(saved.samples)) samples.value = saved.samples.filter((row: SimulationSample) => row && [row.second, row.x, row.altitude, row.z, row.battery, row.heading].every(Number.isFinite)).slice(-600)
    if (Array.isArray(saved.viewpoints)) viewpoints.value = saved.viewpoints.filter((row: ViewpointResult) => row && [row.before, row.after, row.candidates].every(Number.isFinite)).slice(0, 20)
    if (['fixed', 'coverage', 'semantic'].includes(saved.strategy)) strategy.value = saved.strategy
    if (Array.isArray(saved.observations)) observations.value = saved.observations.filter((row: PlantObservation) => row && Number.isInteger(row.target) && row.target >= 0 && row.target < observationTargets.length && Number.isInteger(row.sector) && row.sector >= 0 && row.sector < 8 && Number.isFinite(row.visible) && row.visible >= 0 && row.visible <= 1 && Array.isArray(row.position) && row.position.length === 3 && row.position.every(Number.isFinite) && ['flight', 'viewpoint'].includes(row.source)).slice(-100)
    lastSample = Math.floor(elapsed.value)
    if (stage.value === 'paused') notice.value = '已恢复上次任务，点击“继续巡检”接着执行。'
    if (samples.value.length) messages.value[0]!.text = '已为您恢复本次巡检记录。您可以查看任务状态、调度观察视点，或导出巡检报告。'
  }
} catch { log('已准备新的巡检任务。') }

function resetMission() {
  stage.value = 'idle'; resumeStage.value = 'running'; points.value = route.value.points
  segmentDistance.value = 0; totalDistance.value = 0; elapsed.value = 0; samples.value = []; viewpoints.value = []; observations.value = []; lastSample = -1
  missionId.value = `SIM-${Date.now()}`; modal.value = ''; cameraMode.value = 'overview'; sceneRef.value?.resetView()
  checkpoint(); notify('任务已重置，无人机回到起降点。')
}
function start() {
  if (!ready.value || sceneError.value) return notify('请等待三维场景加载完成。')
  if (stage.value === 'paused') { stage.value = resumeStage.value; checkpoint(); return notify('巡检已继续。') }
  if (running.value) return notify('当前任务正在执行。')
  if (stage.value === 'completed') resetMission()
  stage.value = 'running'; checkpoint(); notify(`开始 ${route.value.name}，播放倍率 ${timeScale.value}×。`)
}
function pause() {
  if (!running.value) return notify('当前没有运行中的巡航。')
  resumeStage.value = stage.value as 'running' | 'returning'; stage.value = 'paused'; checkpoint(); notify('巡检已暂停，可继续任务或安全返航。')
}
function returnHome() {
  if (stage.value === 'idle' || stage.value === 'completed') return notify('无人机已在起降点，无需返航。')
  if (stage.value === 'returning' || stage.value === 'paused' && resumeStage.value === 'returning') { if (stage.value === 'paused') start(); return notify('正在沿安全返航路径返回。') }
  points.value = returnRoute(pose.value.position); segmentDistance.value = 0; stage.value = 'returning'; resumeStage.value = 'returning'; checkpoint(); notify('已切换返航路径：先爬升，再返回起降点并降落。')
}
function sample() {
  const [x, altitude, z] = pose.value.position
  samples.value.push({ second: Math.floor(elapsed.value), x: +x.toFixed(2), altitude: +altitude.toFixed(2), z: +z.toFixed(2), battery: +battery.value.toFixed(2), heading: +pose.value.heading.toFixed(2) })
  samples.value = samples.value.slice(-600)
}
function advance(seconds: number) {
  if (!running.value || !Number.isFinite(seconds)) return
  const simulatedSeconds = Math.max(0, Math.min(seconds, .1)) * timeScale.value
  const step = Math.min(speed.value * simulatedSeconds, Math.max(0, length.value - segmentDistance.value))
  const previousDistance = segmentDistance.value
  segmentDistance.value += step; totalDistance.value += step; elapsed.value += step / speed.value
  if (stage.value === 'running') {
    if (routeId.value === 'maize-adaptive' && previousDistance < adaptivePlan.coarseEnd && segmentDistance.value >= adaptivePlan.coarseEnd) notify('全域巡查已完成，正在前往 M01、M02 执行低空复核。')
    for (const visit of routeObservations(routeId.value)) if (previousDistance < visit.distance && segmentDistance.value >= visit.distance) {
      const visible = sceneRef.value?.observePlant(visit.target, visit.position) ?? 0
      observations.value.push({ target: visit.target, sector: viewSector(visit.position, observationTargets[visit.target]!.point), visible, source: 'flight', position: [...visit.position] })
      targetIndex.value = visit.target
      notify(`${observationTargets[visit.target]!.name}：已完成一个观察方向，视野通畅率 ${Math.round(visible * 100)}%。`)
    }
  }
  if (Math.floor(elapsed.value) !== lastSample) { lastSample = Math.floor(elapsed.value); sample(); checkpoint() }
  if (segmentDistance.value >= length.value) { stage.value = 'completed'; sample(); checkpoint(); notify('任务已结束，无人机已降落。巡检记录可生成报告。') }
  else if (battery.value <= 20 && stage.value === 'running') returnHome()
}
async function optimize() {
  if (!ready.value || optimizing.value || sceneError.value) return
  optimizing.value = true; cameraMode.value = 'observation'; notice.value = strategy.value === 'fixed' ? '正在切换标准观察机位…' : '正在为当前样株选择观察视点…'
  await nextTick()
  const result = await sceneRef.value?.optimizeView()
  if (unmounted) return
  optimizing.value = false
  if (!result) return notify('视点调度已取消，请重试。')
  viewpoints.value.push(result); viewpoints.value = viewpoints.value.slice(-20)
  if (result.target !== undefined && result.sector !== undefined) observations.value.push({ target: result.target, sector: result.sector, visible: 1 - result.after, source: 'viewpoint', position: [...result.position] })
  observations.value = observations.value.slice(-100); checkpoint(); if (modal.value === 'viewpoints') modal.value = ''
  notify(`观察机位已就绪，遮挡比例 ${Math.round(result.before * 100)}% → ${Math.round(result.after * 100)}%。`)
}
function configureRoute() {
  if (stage.value !== 'idle' && stage.value !== 'completed') return notify('请先重置当前任务，再更换航线。')
  routeId.value = draftRoute.value; resetMission(); notify(`已选择 ${route.value.name}。`)
}
function saveReport() {
  if (!samples.value.length) return notify('完成一次巡检后，即可生成任务报告。')
  const report: SimulationReport = { id: missionId.value, createdAt: new Date().toLocaleString('zh-CN'), routeName: route.value.name, status: stage.value, elapsed: elapsed.value, distance: totalDistance.value, observations: observations.value.map(row => ({ ...row, position: [...row.position] })), samples: samples.value.map(row => ({ ...row })), viewpoints: viewpoints.value.map(row => ({ ...row })) }
  reports.value = [report, ...reports.value.filter(row => row.id !== report.id)].slice(0, 5)
  try { localStorage.setItem(REPORT_KEY, JSON.stringify(reports.value)); notify('巡检报告已保存，可查看或导出。') } catch { notify('本地存储空间不足，仍可立即下载当前报告。') }
  modal.value = 'reports'
}
function download(report: SimulationReport, format: 'html' | 'json') {
  const blob = new Blob([format === 'html' ? simulationReportHtml(report) : JSON.stringify({ source: 'simulation', disease_detection: null, ...report }, null, 2)], { type: format === 'html' ? 'text/html;charset=utf-8' : 'application/json;charset=utf-8' })
  const url = URL.createObjectURL(blob), link = document.createElement('a')
  link.href = url; link.download = `玉米巡检报告_${report.id}.${format}`; link.click(); window.setTimeout(() => URL.revokeObjectURL(url), 1000)
  notify(`${format.toUpperCase()} 报告已导出。`)
}
function sendCommand(text = command.value) {
  const value = text.trim(); if (!value) return
  messages.value.push({ role: 'user', text: value }); command.value = ''
  const action = simulationCommand(value)
  if (action === 'start') start()
  else if (action === 'pause') pause()
  else if (action === 'resume') stage.value === 'paused' ? start() : notify('当前没有暂停的任务。')
  else if (action === 'return') returnHome()
  else if (action === 'optimize') { void optimize() }
  else if (action === 'status') notice.value = `当前${status.value}，完成 ${progress.value.toFixed(1)}%，剩余电量 ${battery.value.toFixed(0)}%。`
  else notice.value = '我可以帮助您开始巡检、暂停或继续任务、安全返航，以及优化观察视点。也可以发送“状态”查看任务进度。'
  messages.value.push({ role: 'assistant', text: notice.value }); messages.value = messages.value.slice(-20)
}
async function fullscreen() { if (!viewport.value) return; try { if (document.fullscreenElement) await document.exitFullscreen(); else await viewport.value.requestFullscreen() } catch { notify('浏览器未允许全屏，可直接在当前窗口操作。') } }
function onSceneError(message: string) { sceneError.value = message; if (running.value) pause(); notify(message) }
function suspend() { if (running.value) pause() }
function time(value: number) { return `${String(Math.floor(value / 60)).padStart(2, '0')}:${String(Math.floor(value % 60)).padStart(2, '0')}` }
window.addEventListener('beforeunload', checkpoint)
onBeforeUnmount(() => { unmounted = true; if (running.value) { resumeStage.value = stage.value as 'running' | 'returning'; stage.value = 'paused' } checkpoint(); window.removeEventListener('beforeunload', checkpoint); document.removeEventListener('fullscreenchange', fullscreenChanged) })
</script>

<template>
  <div class="pest-workbench">
    <InspectionHeader title="玉米病害低空智能巡检" :task-name="route.name">
      <template #actions>
        <span class="demo-tag"><Box :size="13" />演示任务</span>
        <button class="button secondary" @click="router.push('/')"><ArrowLeft :size="15" />首页</button>
        <button class="button secondary" :disabled="!samples.length" @click="saveReport"><FileDown :size="15" />生成报告</button>
        <button class="button primary" :disabled="!ready || Boolean(sceneError)" @click="running ? pause() : start()"><Pause v-if="running" :size="15" /><Play v-else :size="15" />{{ running ? '暂停巡检' : stage === 'paused' ? '继续巡检' : stage === 'completed' ? '重新巡检' : '开始巡检' }}</button>
      </template>
    </InspectionHeader>

    <main class="workbench-grid">
      <aside class="control-column">
        <section class="card telemetry-card">
          <div class="card-title"><h2><Activity :size="17" />飞行状态</h2><span class="state-badge" :class="{ live: running }"><i></i>{{ status }}</span></div>
          <div class="drone-identity"><div class="drone-icon"><Navigation :size="22" /></div><div><strong>植保巡检无人机</strong><span>UAV-01 <i>·</i> 一号试验田</span></div></div>
          <div class="battery-line"><span><Battery :size="15" />剩余电量</span><strong data-testid="sim-battery">{{ battery.toFixed(0) }}<small>%</small></strong></div><div class="battery-track"><i :style="{ width: `${battery}%` }"></i></div>
          <div class="telemetry-grid"><div><span><Mountain :size="14" />飞行高度</span><strong data-testid="sim-altitude">{{ pose.position[1].toFixed(1) }}<small>m</small></strong></div><div><span><Gauge :size="14" />当前速度</span><strong>{{ running ? speed.toFixed(1) : '0.0' }}<small>m/s</small></strong></div><div><span><Navigation :size="14" />航向角</span><strong>{{ ((pose.heading + 360) % 360).toFixed(0) }}<small>°</small></strong></div><div><span><Clock :size="14" />任务时长</span><strong class="time-value" data-testid="sim-elapsed">{{ time(elapsed) }}</strong></div></div>
          <div class="coordinate-line"><span>场景坐标</span><span data-testid="sim-position">X {{ pose.position[0].toFixed(1) }} · Z {{ pose.position[2].toFixed(1) }}</span></div>
        </section>

        <section class="card task-card"><div class="card-title"><h2><Layers :size="17" />任务控制</h2><span class="section-kicker">MISSION</span></div>
          <div class="tool-grid"><button @click="openRoutes"><Route :size="21" /><span>航线规划</span><ChevronRight :size="12" /></button><button :disabled="!ready" @click="modal = 'viewpoints'"><ScanEye :size="21" /><span>视点调度</span><ChevronRight :size="12" /></button><button @click="modal = 'reports'"><FileDown :size="21" /><span>巡检报告</span><ChevronRight :size="12" /></button><button @click="modal = 'models'"><Settings2 :size="21" /><span>运行配置</span><ChevronRight :size="12" /></button></div>
          <div class="active-route"><span>当前方案</span><strong>{{ route.name }}</strong><p>{{ route.description }}</p><div><span>{{ route.points.length }} 个航点</span><span>{{ routeLength(route.points).toFixed(0) }} m</span></div></div>
          <label class="form-row">巡航速度<select v-model.number="speed" aria-label="巡航速度" @change="checkpoint"><option :value="2">2 m/s</option><option :value="4">4 m/s</option><option :value="8">8 m/s</option></select></label>
          <label class="form-row">播放倍率<select v-model.number="timeScale" aria-label="播放倍率" @change="checkpoint"><option :value="1">1×</option><option :value="2">2×</option><option :value="4">4×</option></select></label>
          <div class="paired-buttons"><button class="button secondary" :disabled="stage === 'idle' || stage === 'completed'" @click="returnHome"><Navigation :size="14" />安全返航</button><button class="button secondary" :disabled="optimizing" @click="modal = 'reset'"><RotateCcw :size="14" />重置</button></div>
        </section>
        <div class="control-footer"><i></i>三维场景已{{ ready ? '就绪' : '加载中' }}<span>任务记录自动保存</span></div>
      </aside>

      <section class="workspace-column">
        <div ref="viewport" class="scene-viewport">
          <PestSimulationScene ref="sceneRef" :points="points" :position="pose.position" :heading="pose.heading" :running="running" :camera-mode="cameraMode" :target-index="targetIndex" :strategy="strategy" :visited-sectors="visitedSectors" @advance="advance" @ready="ready = true" @error="onSceneError" @suspend="suspend" />
          <div class="scene-heading"><div><span class="live-dot"></span><strong>一号玉米试验田</strong><span class="scene-subtitle">作业区域 A-01</span></div><span class="scene-mode">三维演示</span></div>
          <div class="camera-toolbar" aria-label="视角切换"><button v-for="mode in [{ id: 'overview', label: '全景' }, { id: 'follow', label: '跟随' }, { id: 'top', label: '俯视' }]" :key="mode.id" :aria-pressed="cameraMode === mode.id" :disabled="optimizing" @click="cameraMode = mode.id"><Camera :size="14" />{{ mode.label }}</button><i></i><button aria-label="重置观察视角" :disabled="optimizing" @click="cameraMode = 'overview'; sceneRef?.resetView()"><RotateCcw :size="15" /></button><button :aria-label="isFullscreen ? '退出场景全屏' : '切换场景全屏'" :aria-pressed="isFullscreen" @click="fullscreen"><Maximize2 :size="15" /></button></div>
          <div v-if="cameraMode === 'observation' && lastView" class="viewpoint-hud"><ScanEye :size="15" /><div><strong>{{ observationTargets[lastView.target ?? targetIndex]!.name }}</strong><span>{{ strategyName }} · 视野通畅 {{ Math.round((1 - lastView.after) * 100) }}%</span></div><button @click="cameraMode = 'overview'">返回全景</button></div>
          <div class="scene-footer"><span><i class="route-line"></i>计划航线<i class="target-dot"></i>重点样株</span><span>拖动旋转 · 滚轮缩放</span></div>
        </div>

        <section class="card mission-progress"><div class="progress-heading"><div><span class="state-dot" :class="{ live: running }"></span><strong>{{ status }}</strong><span class="progress-caption">{{ stage === 'returning' ? '正在返回起降点' : route.name }}</span></div><strong data-testid="sim-progress">{{ progress.toFixed(1) }}<small>%</small></strong></div><div class="progress-track"><i :style="{ width: `${progress}%` }"></i></div><div class="progress-details"><span>航点 <b>{{ pose.waypoint + 1 }} / {{ points.length }}</b></span><span>航程 <b>{{ totalDistance.toFixed(1) }} m</b></span><span>预计剩余 <b>{{ time(remaining) }}</b></span><span>{{ timeScale }}×</span></div>
          <div v-if="routeId === 'maize-adaptive'" class="workflow"><span v-for="(step, index) in ['区域巡查', '重点复核', '返航归档']" :key="step" :class="{ active: phaseIndex === index, done: phaseIndex > index }"><i><Check v-if="phaseIndex > index" :size="11" /><template v-else>{{ index + 1 }}</template></i>{{ step }}</span></div>
        </section>

        <section class="card plant-panel"><div class="card-title"><h2><Leaf :size="16" />植株观察</h2><span>已观测 <b>{{ observedPlants }}</b> / {{ observationTargets.length }} 株</span><button @click="modal = 'viewpoints'">视点调度 <ChevronRight :size="13" /></button></div><div class="plant-grid"><button v-for="(target, index) in observationTargets" :key="target.name" class="plant-card" :aria-pressed="targetIndex === index" :disabled="optimizing" @click="targetIndex = index"><div><strong>{{ target.name.split(' · ')[0] }}</strong><span :class="{ observed: observationCoverage(observations, index) > 0 }">{{ plantState(index) }}</span></div><p>{{ target.name.split(' · ')[1] }}</p><div class="coverage-dots"><i v-for="sector in 8" :key="sector" :class="{ seen: observations.some(item => item.target === index && item.sector === sector - 1 && item.visible >= .5) }"></i></div><small>{{ observationCoverage(observations, index) }} / 8 观察方向</small></button></div></section>
        <section class="card log-panel"><div class="card-title"><h2><Activity :size="16" />任务动态</h2><span>最近 {{ Math.min(logs.length, 20) }} 条</span></div><div class="log-scroll"><div v-for="(entry, index) in logs.slice(0, 20)" :key="index"><time>{{ entry.time }}</time><i></i><span>{{ entry.message }}</span></div><div v-if="!logs.length"><time>--:--:--</time><i></i><span>任务准备就绪，等待开始巡检。</span></div></div></section>
      </section>

      <aside class="card assistant-column"><div class="assistant-heading"><div class="assistant-avatar"><Box :size="23" /></div><div><h2>巡检助手</h2><span><i></i>任务调度与观察建议</span></div></div><div class="mission-overview"><span>当前任务</span><strong>{{ route.name }}</strong><div><span>{{ status }}</span><span>{{ observations.length }} 条观察记录</span></div></div><div class="chat-history" aria-live="polite"><div v-for="(message, index) in messages" :key="index" class="chat-message" :class="message.role"><span>{{ message.role === 'user' ? '我' : '巡检助手' }}</span><p>{{ message.text }}</p></div><div v-if="lastView" class="view-summary" data-testid="optimization-result"><span><ScanEye :size="14" />观察视点已更新</span><strong>{{ Math.round((1 - lastView.after) * 100) }}<small>% 视野通畅</small></strong><p>{{ lastView.candidates }} 个候选机位 · {{ viewpoints.length }} 次调度</p></div></div><div class="assistant-bottom"><div class="quick-commands"><button @click="sendCommand('状态')">任务状态</button><button :disabled="optimizing" @click="sendCommand('优化视点')">优化视点</button><button @click="sendCommand('返航')">返航</button></div><form class="command-form" @submit.prevent="sendCommand()"><input v-model="command" aria-label="巡检调度指令" placeholder="输入指令，如：开始巡检、暂停…" maxlength="120" /><button aria-label="发送指令" :disabled="!command.trim()"><Send :size="17" /></button></form><button class="report-shortcut" @click="modal = 'reports'"><FileDown :size="15" />任务报告<span>{{ reports.length }} 份</span><ChevronRight :size="13" /></button></div></aside>
    </main>
    <div class="task-toast" role="status"><span></span>{{ notice }}</div>

    <div v-if="modal" class="modal-backdrop" @click.self="!optimizing && (modal = '')"><section class="workbench-modal" role="dialog" aria-modal="true" :aria-label="modal === 'routes' ? '航线规划' : modal === 'models' ? '运行配置' : modal === 'viewpoints' ? '视点调度' : modal === 'reset' ? '重置任务' : '巡检报告'"><div class="modal-title"><div><span>玉米病害低空智能巡检</span><h2>{{ modal === 'routes' ? '航线规划' : modal === 'models' ? '运行配置' : modal === 'viewpoints' ? '视点调度' : modal === 'reset' ? '重置任务' : '巡检报告' }}</h2></div><button aria-label="关闭弹窗" :disabled="optimizing" @click="modal = ''"><X :size="20" /></button></div>
      <template v-if="modal === 'routes'"><p class="modal-description">根据本次作业范围选择巡检方案。</p><button v-for="(item, index) in simulationRoutes" :key="item.id" class="route-option" :aria-pressed="draftRoute === item.id" @click="draftRoute = item.id"><span class="route-icon"><Route :size="23" /></span><div><strong>{{ item.name }}</strong><span v-if="index === 0" class="recommended">推荐</span><p>{{ item.description }}</p><small>{{ item.points.length }} 个航点 <i>·</i> {{ routeLength(item.points).toFixed(0) }} m <i>·</i> 预计 {{ time(routeLength(item.points) / speed) }}</small></div><span class="radio-mark"><Check v-if="draftRoute === item.id" :size="13" /></span></button><p v-if="stage !== 'idle' && stage !== 'completed'" class="inline-notice">当前任务尚未结束，请先重置任务后更换方案。</p><div class="modal-footer"><button class="button secondary" @click="modal = ''">取消</button><button class="button primary" :disabled="stage !== 'idle' && stage !== 'completed'" @click="configureRoute">应用方案</button></div></template>
      <template v-if="modal === 'viewpoints'"><p class="modal-description">为目标植株选择观察方向，获得更完整的叶片视野。</p><label class="modal-field">观察植株<select v-model.number="targetIndex" aria-label="观察植株" :disabled="optimizing"><option v-for="(target, index) in observationTargets" :key="target.name" :value="index">{{ target.name }}</option></select></label><label class="modal-field">调度策略<select v-model="strategy" aria-label="调度策略" :disabled="optimizing" @change="checkpoint"><option value="fixed">标准观察</option><option value="coverage">覆盖优先</option><option value="semantic">重点区域优先</option></select></label><div class="strategy-description"><ScanEye :size="20" /><p>{{ strategy === 'fixed' ? '使用标准观察机位，快速查看目标植株。' : strategy === 'coverage' ? '优先选择尚未覆盖的观察方向，补全植株记录。' : '综合叶片遮挡和观察记录，选择更适合复核的机位。' }}</p></div><div class="observation-metrics"><div><span>已覆盖方向</span><strong>{{ observationCoverage(observations, targetIndex) }} <small>/ 8</small></strong></div><div><span>已调度视点</span><strong>{{ viewpoints.length }} <small>次</small></strong></div></div><div class="modal-footer"><button class="button secondary" :disabled="optimizing" @click="modal = ''">取消</button><button class="button primary" :disabled="!ready || optimizing || Boolean(sceneError)" @click="optimize"><ScanEye :size="15" />{{ optimizing ? '正在调度…' : '调度观察视点' }}</button></div></template>
      <template v-if="modal === 'models'"><div class="config-summary"><div><span>任务环境</span><strong>三维场景演示</strong></div><div><span>场景资源</span><strong>一号玉米试验田</strong></div><div><span>记录保存</span><strong>当前浏览器 · 自动保存</strong></div></div><p class="modal-description">当前任务使用内置场景资源，无需上传视频。业务素材与检测模型可通过素材中心统一管理。</p><details class="model-guide"><summary>模型权重上传说明</summary><ol><li>在素材中心选择对应业务的专用模型分类。</li><li>按分类提示使用固定文件名，子目录留空后上传。</li><li>服务端需安装推理依赖；替换已加载的权重后重启服务。</li></ol><p>素材中心会自动显示当前分类要求的模型文件名。</p></details><div class="modal-footer"><button class="button secondary" @click="modal = ''">关闭</button><RouterLink class="button primary" to="/assets">打开素材中心 <MoveUpRight :size="15" /></RouterLink></div></template>
